"use client";

import { useState } from "react";

export default function ContactForm() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    message: "",
  });

  const [isSubmitted, setIsSubmitted] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      await new Promise((resolve) => setTimeout(resolve, 500));
      setIsSubmitted(true);
      setFormData({ name: "", email: "", message: "" });
      setTimeout(() => {
        setIsSubmitted(false);
      }, 3000);
    } catch (error) {
      console.error("Error submitting form:", error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <section className="min-h-screen bg-white text-black flex items-center justify-center px-6 py-20">
      <div className="w-full max-w-5xl">
        <div className="grid grid-cols-2 gap-12">
          {/* Left Column - Contact Info */}
          <div className="flex flex-col justify-start">
            <h1 className="text-4xl font-light mb-12">Get in touch</h1>

            {/* Email */}
            <div className="mb-8">
              <p className="text-sm text-gray-600 font-light mb-1">Email:</p>
              <p className="text-base font-light">contact@example.com</p>
            </div>

            {/* Phone */}
            <div className="mb-8">
              <p className="text-sm text-gray-600 font-light mb-1">Phone:</p>
              <p className="text-base font-light">+1 (555) 123-4567</p>
            </div>

            {/* Address */}
            <div className="mb-12">
              <p className="text-sm text-gray-600 font-light mb-2">Address:</p>
              <p className="text-base font-light leading-relaxed">
                123 Innovation Avenue, Suite 456
                <br />
                Tech District, San Francisco, CA 94107
                <br />
                United States
              </p>
            </div>

            {/* Social Links */}
            <div>
              <p className="text-sm text-gray-600 font-light mb-4">Follow us</p>
              <div className="flex gap-3">
                <a
                  href="#"
                  className="w-8 h-8 rounded-full bg-black text-white flex items-center justify-center text-xs hover:bg-gray-800 transition-colors"
                >
                  f
                </a>
                <a
                  href="#"
                  className="w-8 h-8 rounded-full bg-black text-white flex items-center justify-center text-xs hover:bg-gray-800 transition-colors"
                >
                  𝕏
                </a>
                <a
                  href="#"
                  className="w-8 h-8 rounded-full bg-black text-white flex items-center justify-center text-xs hover:bg-gray-800 transition-colors"
                >
                  in
                </a>
                <a
                  href="#"
                  className="w-8 h-8 rounded-full bg-black text-white flex items-center justify-center text-xs hover:bg-gray-800 transition-colors"
                >
                  ig
                </a>
              </div>
            </div>
          </div>

          {/* Right Column - Form */}
          <div>
            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Name & Email Row */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs text-gray-600 font-light block mb-2">
                    Your Name
                  </label>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    placeholder="Your full name"
                    required
                    className="w-full bg-gray-100 text-black placeholder-gray-500 text-sm font-light px-3 py-2 focus:outline-none focus:ring-1 focus:ring-black"
                  />
                </div>
                <div>
                  <label className="text-xs text-gray-600 font-light block mb-2">
                    Email address
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    placeholder="Your email address"
                    required
                    className="w-full bg-gray-100 text-black placeholder-gray-500 text-sm font-light px-3 py-2 focus:outline-none focus:ring-1 focus:ring-black"
                  />
                </div>
              </div>

              {/* Message Field */}
              <div>
                <label className="text-xs text-gray-600 font-light block mb-2">
                  Message
                </label>
                <textarea
                  name="message"
                  value={formData.message}
                  onChange={handleChange}
                  placeholder="Write something..."
                  rows="6"
                  required
                  className="w-full bg-gray-100 text-black placeholder-gray-500 text-sm font-light px-3 py-2 focus:outline-none focus:ring-1 focus:ring-black resize-none"
                />
              </div>

              {/* Submit Button */}
              <div className="pt-2">
                {isSubmitted ? (
                  <div className="text-gray-600 font-light text-sm">
                    ✓ Thank you. We'll be in touch soon.
                  </div>
                ) : (
                  <button
                    type="submit"
                    disabled={isLoading}
                    className="w-full bg-black text-white font-light py-3 hover:bg-gray-800 transition-colors duration-300 disabled:bg-gray-600 text-sm"
                  >
                    {isLoading ? "Sending..." : "Send Message"}
                  </button>
                )}
              </div>
            </form>
          </div>
        </div>
      </div>
    </section>
  );
}
